import React from 'react';
import { useManagerStore } from '../../store/managerStore';
import { useNfcCooldown } from '../../hooks/useNfcCooldown';

export default function NfcToggle() {
  const nfcEnabled = useManagerStore(state => state.nfcEnabled);
  const setNfcEnabled = useManagerStore(state => state.setNfcEnabled);
  const { isNfcLocked, remainingSeconds } = useNfcCooldown();

  return (
    <button
      onClick={() => setNfcEnabled(!nfcEnabled)}
      title={nfcEnabled ? "Czytnik NFC włączony. Kliknij by wyłączyć." : "Czytnik NFC wyłączony. Kliknij by włączyć."}
      className={`relative p-2 rounded-lg transition-colors flex items-center justify-center shrink-0 ${
        nfcEnabled
          ? 'bg-purple-100 hover:bg-purple-200 text-purple-700 border border-purple-300'
          : 'bg-slate-700 hover:bg-slate-600 text-slate-300 border border-slate-600'
      }`}
    >
      <i className={`ph ${nfcEnabled ? 'ph-waves' : 'ph-waves-slash'} text-xl`}></i>
      {isNfcLocked && nfcEnabled && (
        <span className="absolute -bottom-1 -right-1 bg-red-500 text-white text-[9px] font-bold px-1 rounded">
          {remainingSeconds}s
        </span>
      )}
    </button>
  );
}
